mapper.insert:
INSERT INTO artifact_version (
    artifact_id, version_number, content_ref, content_format,
    source_run_id, change_summary, created_at
) VALUES (
    #{artifactId}, #{versionNumber}, #{contentRef}, #{contentFormat},
    #{sourceRunId}, #{changeSummary}, #{createdAt}
)

mapper.select:
SELECT id, artifact_id, version_number, content_ref, content_format,
       source_run_id, change_summary, created_at
FROM artifact_version
WHERE artifact_id = #{artifactId}
  AND id = #{id}
